import Color from 'color';

/**
 * Makes the project color the primary color of the whole app.
 *
 * `--primary` and its shades are generated by Sass from a fixed purple (see styles/themes/mixins/generate-colors.scss).
 * This overrides them on <body> with the same mixing rules, expressed with CSS color-mix() so the active theme
 * (light, dark or auto) is resolved by the browser: the themes expose the mix colors as --primary-mix-pos (mixed in for
 * the positive steps) and --primary-mix-neg (negative steps). The project color itself is used as is in every theme.
 */

// Suffix -> signed percentage, mirrors $step-mapping in styles/_colors.scss
const STEPS: Record<string, number> = {
	'10': 10,
	'25': 25,
	'50': 50,
	'75': 75,
	'90': 90,
	'110': -90,
	'125': -75,
	'150': -50,
	'175': -25,
	'190': -10,
};

export const PRIMARY_VARIABLES = [
	'--primary',
	'--primary-alt',
	...Object.keys(STEPS).map((suffix) => `--primary-${suffix}`),
];

export function getProjectPrimaryVars(color: string | null | undefined): Record<string, string> | null {
	if (!color) return null;

	let hex: string;

	try {
		hex = Color(color).hex();
	} catch {
		return null;
	}

	const vars: Record<string, string> = {
		'--primary': hex,
	};

	for (const [suffix, step] of Object.entries(STEPS)) {
		const mixWith = step > 0 ? 'var(--primary-mix-pos)' : 'var(--primary-mix-neg)';
		vars[`--primary-${suffix}`] = `color-mix(in srgb, var(--primary) ${Math.abs(step)}%, ${mixWith})`;
	}

	vars['--primary-alt'] = 'var(--primary-10)';

	return vars;
}

export function applyProjectPrimary(color: string | null | undefined): void {
	for (const name of PRIMARY_VARIABLES) document.body.style.removeProperty(name);

	// Without color-mix() support the stock palette stays, instead of broken colors
	if (!CSS.supports('color', 'color-mix(in srgb, red, blue)')) return;

	const vars = getProjectPrimaryVars(color);
	if (!vars) return;

	for (const [name, value] of Object.entries(vars)) document.body.style.setProperty(name, value);
}
